package com.huy.enterprise.product; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/product-categories") @RequiredArgsConstructor public class ProductCategoryController {private final ProductCategoryService service;@GetMapping List<CategoryResponse> all(){return service.all();}@PostMapping @ResponseStatus(HttpStatus.CREATED) CategoryResponse create(@Valid @RequestBody CategoryRequest r){return service.create(r);}@PutMapping("/{id}") CategoryResponse update(@PathVariable UUID id,@Valid @RequestBody CategoryRequest r){return service.update(id,r);}}
